<?php
/** Create ClientConfig groups and parameterise current templates without reimporting static bodies. */
if(PHP_SAPI!=='cli'||!in_array('--apply',$argv,true))exit("Usage: php tools/modx/configure-contacts.php --apply\n");
$root=dirname(__DIR__,2).'/';define('MODX_API_MODE',true);require $root.'public/index.php';$modx->initialize('mgr');require_once $root.'cms/elements/TemplateRegistry.php';require_once $root.'cms/elements/Contacts.php';
use MODX\Revolution\{modTemplate,modTemplateVarResource,modSnippet,modCategory,modSystemSetting,modPlugin,modPluginEvent};
$client=$modx->getService('clientconfig','ClientConfig',MODX_CORE_PATH.'components/clientconfig/model/clientconfig/');if(!$client)throw new RuntimeException('ClientConfig unavailable');
$backup=[];foreach([modTemplate::class,modTemplateVarResource::class,'cgGroup','cgSetting'] as $class)foreach($modx->getCollection($class) as $o)$backup[$class][]=$o->toArray();file_put_contents($root.'cms/backups/before-clientconfig-'.date('Ymd-His').'.json',json_encode($backup,JSON_UNESCAPED_UNICODE|JSON_PRETTY_PRINT));
$definitions=json_decode(file_get_contents($root.'cms/contact-settings.json'),true,512,JSON_THROW_ON_ERROR);$keys=[];
foreach($definitions['groups'] as $rank=>$group){$g=$modx->getObject('cgGroup',['label'=>$group['label']]);if(!$g)$g=$modx->newObject('cgGroup');$g->fromArray(['label'=>$group['label'],'description'=>$group['description'],'sortorder'=>$rank]);if(!$g->save())throw new RuntimeException('Group save failed');foreach($group['fields'] as $order=>$field){$s=$modx->getObject('cgSetting',['key'=>$field['key']]);$new=!$s;if($new)$s=$modx->newObject('cgSetting');$data=['key'=>$field['key'],'label'=>$field['label'],'xtype'=>$field['xtype']??'textfield','description'=>$field['description']??'Общее значение для всех страниц сайта.','is_required'=>1,'sortorder'=>$order,'group'=>$g->get('id'),'options'=>'','process_options'=>0,'source'=>0];if($new)$data+=['value'=>$field['value'],'default'=>$field['value']];$s->fromArray($data);if(!$s->save())throw new RuntimeException('Setting save failed');$keys[]=$field['key'];}}
$cat=$modx->getObject(modCategory::class,['category'=>'Контакты']);if(!$cat){$cat=$modx->newObject(modCategory::class);$cat->set('category','Контакты');$cat->save();}
foreach(['ZubrPhone'=>"return '+' . preg_replace('/[^0-9]/', '', (string)\$input);",'ZubrStreet'=>"return trim(preg_replace('/^[^,]+,\\s*/u', '', (string)\$input));"] as $name=>$code){$s=$modx->getObject(modSnippet::class,['name'=>$name]);if(!$s)$s=$modx->newObject(modSnippet::class);$s->fromArray(['name'=>$name,'category'=>$cat->get('id'),'description'=>'Форматирование контакта из ClientConfig.','snippet'=>$code]);if(!$s->save())throw new RuntimeException('Modifier save failed');}
$count=0;foreach($modx->getCollection(modTemplate::class,Zubr\Site\TemplateRegistry::criteria()) as $t){$t->set('content',Zubr\Site\Contacts::prepareTemplate($t->get('content')));if(!$t->save())throw new RuntimeException('Template save failed');$count++;}
foreach($modx->getCollection(modTemplateVarResource::class,['tmplvarid:IN'=>[1,2]]) as $tv){$tv->set('value',Zubr\Site\Contacts::prepareTemplate($tv->get('value')));$tv->save();}
// Saving ClientConfig clears the rendered resource cache.
$clear=$modx->getObject(modSystemSetting::class,['key'=>'clientconfig.clear_cache']);if(!$clear){$clear=$modx->newObject(modSystemSetting::class);$clear->fromArray(['key'=>'clientconfig.clear_cache','namespace'=>'clientconfig','area'=>'default','xtype'=>'combo-boolean'],'',true,true);}$clear->set('value','1');$clear->save();
$plugin=$modx->getObject(modPlugin::class,['name'=>'Обновление общих контактов']);if(!$plugin)$plugin=$modx->newObject(modPlugin::class);$plugin->fromArray(['name'=>'Обновление общих контактов','category'=>$cat->get('id'),'description'=>'Очищает кеш страниц MODX 3 после сохранения ClientConfig, включая общие чанки.','disabled'=>0,'plugincode'=>"\$modx->cacheManager->refresh(['resource'=>['contexts'=>['web']]]);\n"]);$plugin->save();$criteria=['pluginid'=>$plugin->get('id'),'event'=>'ClientConfig_ConfigChange'];if(!$modx->getObject(modPluginEvent::class,$criteria)){$event=$modx->newObject(modPluginEvent::class);$event->fromArray($criteria+['priority'=>10],'',true,true);$event->save();}
$modx->cacheManager->refresh();file_put_contents($root.'cms/clientconfig-setup.json',json_encode(['package'=>'clientconfig-2.5.0-pl','groups'=>array_column($definitions['groups'],'label'),'keys'=>$keys,'templates'=>$count],JSON_UNESCAPED_UNICODE|JSON_PRETTY_PRINT));echo "ClientConfig: ".count($keys)." settings, $count templates.\n";
